abbrev Space := Fin 3 → ℝ
abbrev Field (F : Type*) := ℝ → Space → F

def timeD [NormedAddCommGroup F] [NormedSpace ℝ F] (v : Field F) : Field F :=
  fun t x => derivWithin (fun s => v s x) (Set.Ici 0) t

def spaceD [NormedAddCommGroup F] [NormedSpace ℝ F] (i : Fin 3) (v : Field F) : Field F :=
  fun t x => fderiv ℝ (v t) x (Pi.single i 1)

def Smooth [NormedAddCommGroup F] [NormedSpace ℝ F] (v : Field F) : Prop :=
  ContDiffOn ℝ (⊤ : ℕ∞) (fun z : ℝ × Space => v z.1 z.2) (Set.Ici 0 ×ˢ Set.univ)

def IsMaterialFlow (u : Field Space) (X : ℝ → Space → Space) : Prop :=
  (∀ a, X 0 a = a) ∧
  ∀ a t, 0 ≤ t → HasDerivWithinAt (fun s => X s a) (u t (X t a)) (Set.Ici 0) t

/-- The arithmetic exponent in base size `N` at three prescribed wire weights. -/
def formalOmega (F : Type*) [Field F] (w12 w23 w31 : ℝ) : ℝ :=
  sInf {τ : ℝ | FormalAdmissibleExponent F w12 w23 w31 τ}

/-- The square matrix multiplication exponent over every field. -/
theorem square_exponent (F : Type*) [Field F] : formalOmega F 1 1 1 = (9 : ℝ) / 4 := by
  sorry

theorem rectangular_exponent (F : Type*) [Field F] (a b c : ℝ) :
    formalOmega F a b c =
      let A := max a 0
      let B := max b 0
      let C := max c 0
      let x := max A (max B C)
      let z := min A (min B C)
      let y := A + B + C - x - z
      x + y + (max ((x + y) * z - x * y) 0) ^ 2 / (4 * x * y * z) := by
  sorry

def dualExponent (ω : ℝ → ℝ) : ℝ :=
  sSup {t : ℝ | t ∈ Set.Icc 0 1 ∧ ω t = 2}

def formalAlpha (F : Type*) [Field F] : ℝ := dualExponent (formalOmega F 1 1)

theorem dual_exponent (F : Type*) [Field F] : formalAlpha F = (1 : ℝ) / 2 := by
  sorry
